// Optional offline browser acceptance test: generated media, no provider calls.
const {chromium}=require(process.env.VSTD_PLAYWRIGHT_MODULE || '@playwright/test');
const fs=require('node:fs');const http=require('node:http');const assert=require('node:assert/strict');
const source=fs.readFileSync(require('node:path').join(__dirname,'../templates/avatar.js'),'utf8');
const actions=[];
const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;background:#e8e4dc;color:#173c39;font-family:Arial}main{padding:80px}h1{font-size:56px;max-width:700px}p{font-size:26px}.stripe{position:absolute;bottom:120px;left:0;width:100%;height:60px;background:#d8b48c}button{font-size:18px;padding:12px;margin-right:10px}</style></head><body><main><p>VESSICA · LOCAL VISUAL QA</p><h1>An avatar over the slide,<br>without a video background</h1><p>The colored test figure verifies transparency and placement.</p><button id="wake">Wake</button><button id="sleep">Sleep</button></main><div class="stripe"></div><script>${source}</script><script>
window.routes=[];window.sent=[];window.errors=[];
const input=new AudioContext();const tone=input.createOscillator(),gain=input.createGain(),out=input.createMediaStreamDestination();gain.gain.value=0;tone.connect(gain).connect(out);tone.start();
const picture=document.createElement('canvas');picture.width=320;picture.height=640;const paint=picture.getContext('2d');function draw(){paint.fillStyle='#00ff00';paint.fillRect(0,0,320,640);paint.fillStyle='#f0b598';paint.beginPath();paint.arc(160,110,55,0,7);paint.fill();paint.fillStyle='#364b89';paint.fillRect(85,170,150,300);paint.fillStyle='#202e4f';paint.fillRect(100,470,45,165);paint.fillRect(175,470,45,165);requestAnimationFrame(draw)}draw();const videoStream=picture.captureStream(30);
class Socket{constructor(){this.readyState=1;this.bufferedAmount=0;setTimeout(()=>this.onmessage?.({data:JSON.stringify({type:'session.state_updated',state:'connected'})}),30)}send(s){window.sent.push(JSON.parse(s))}close(){this.readyState=3}}
class Room{constructor(){this.handlers={};this.canPlaybackAudio=true}on(n,f){this.handlers[n]=f}async connect(){this.handlers.track({kind:'video',attach(video){video.srcObject=videoStream}});this.handlers.track({kind:'audio',attach(){const a=document.createElement('audio');a.srcObject=out.stream;return a}})}async startAudio(){}disconnect(){}}
const avatar=VSTDAvatar.create({route:v=>window.routes.push(v),unavailable:()=>window.errors.push('unavailable')},{load:async()=>({Room,RoomEvent:{TrackSubscribed:'track',Disconnected:'disconnect',AudioPlaybackStatusChanged:'audio'},Track:{Kind:{Video:'video',Audio:'audio'}}}),WebSocket:Socket});avatar.attach(out.stream);
document.getElementById('wake').onclick=async()=>{await input.resume();avatar.begin()};document.getElementById('sleep').onclick=()=>avatar.end();window.avatar=avatar;window.gain=gain;
</script></body></html>`;
const server=http.createServer((req,res)=>{if(req.url.startsWith('/api/avatar/')){let body='';req.on('data',b=>body+=b);req.on('end',()=>{actions.push([req.url,JSON.parse(body)]);res.setHeader('Content-Type','application/json');res.end(JSON.stringify({ws_url:'wss://test.example',livekit_url:'wss://room.example',livekit_client_token:'test-token'}))})}else{res.setHeader('Content-Type','text/html');res.end(html)}});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1280,height:720}});page.on('pageerror',e=>console.error(e));await page.goto('http://127.0.0.1:'+server.address().port);assert.equal(actions.length,0);await page.click('#wake');await page.waitForFunction(()=>routes.includes(true));await page.waitForTimeout(500);const pixels=await page.evaluate(()=>{const c=document.querySelector('canvas[aria-label="Vessica"]'),ctx=c.getContext('2d');return {corner:[...ctx.getImageData(0,0,1,1).data],person:[...ctx.getImageData(c.width/2,c.height/2,1,1).data],rect:c.getBoundingClientRect().toJSON(),hidden:c.hidden}});assert.equal(pixels.corner[3],0);assert.equal(pixels.person[3],255);assert.equal(pixels.hidden,false);assert(pixels.rect.x>900);await page.screenshot({path:'/tmp/vessica-liveavatar-qa.png'});await page.evaluate(()=>gain.gain.value=.1);await page.waitForFunction(()=>sent.some(e=>e.type==='agent.speak'&&e.audio.length>0));await page.evaluate(()=>gain.gain.value=0);await page.waitForFunction(()=>sent.some(e=>e.type==='agent.speak_end'));await page.click('#sleep');await page.waitForFunction(()=>document.querySelectorAll('canvas[aria-label="Vessica"]').length===0);assert(actions.some(([url])=>url.endsWith('/stop')));assert.equal(await page.evaluate(()=>routes.at(-1)),false);console.log(JSON.stringify({passed:true,pixels,requests:actions.map(a=>a[0]),screenshot:'/tmp/vessica-liveavatar-qa.png'}));}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1});
